int function(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] data = schema.toByteArray(message);
    int size = data.length;
    if (size > 512000) {  // 500KB is the max size for a single message
        throw new IOException("Message is too large");
    }
    out.write(CodedOutputStream.computeRawVarint32Size(size));
    CodedOutputStream output = CodedOutputStream.newInstance(out, buffer);
