    Map<String, Object> currentMappings = mappings.getSourceAsMap();
    Map<String, Object> currentProperties = (Map<String, Object>) currentMappings.get("properties");
    if (currentProperties == null) {
        return Collections.emptyMap();
    }

    Map<String, Object> result = new HashMap<>();
    Map<String, Object> historyMappings = getHistoryMappings(tableName);
    Map<String, Object> historyProperties = (Map<String, Object>) historyMappings.get("properties");
    if (historyProperties == null) {
        return currentProperties;
    }

    for (Map.Entry<String, Object> entry : currentProperties.entrySet()) {
        if (!historyProperties.containsKey(entry.getKey())) {
            result.put(entry.getKey(), entry.getValue());
        }
    }

    return result;
}

