    while (start < end) {
        long nextStart = Math.min(start + FETCH_DATA_DURATION, end);
        timeRanges.add(new TimeRange(start, nextStart));
        start = nextStart;
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> result = new ArrayList<>();
    long duration = end - start;
    if (duration <= FETCH_DATA_DURATION) {
        result.add(new TimeRange(start, end));
    } else {
        for (long i = start; i < end; i += FETCH_DATA_DURATION) {
            long newEnd = Math.min(i + FETCH_DATA_DURATION, end);
            result.add(new TimeRange(i, newEnd));
        }
    }
    return result;
}

