static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int month = (int) (timeBucket % 10000 / 100);
    int day = (int) (timeBucket % 100);

    if (dayStep == 0) {
        return timeBucket;
    }

    if (dayStep == 1) {
        if (day <= 3) {
            day = 1;
        } else if (day <= 6) {
            day = 4;
        } else if (day <= 9) {
            day = 7;
        } else {
            day = 10;
        }
    } else if (dayStep == 2) {
        if (day <= 2) {
            day = 1;
        } else if (day <= 5) {
            day = 4;
        } else if (day <= 8) {
            day = 7;
        } else {
            day = 10;
        }
    } else if (dayStep == 3) {
        if (day <= 1) {
            day = 1;
        } else if (day <= 3) {
            day = 2;
        } else if (day <= 5) {
            day = 3;
        } else if (day <= 7) {
            day = 4;
        } else if (day <= 9) {
            day = 5;
        } else {
            day = 6;
        }
    } else if (dayStep == 4) {
        if (day <= 1) {
            day = 1;
        } else if (day <= 2) {
            day = 2;
        } else if (day <= 3) {
            day = 3;
        } else if (day <= 4) {
            day = 4;
        } else if (day <= 5) {
            day = 5;
        } else if (day <= 6) {
            day = 6;
        } else {
            day = 7;
        }
    } else if (dayStep == 5) {
        day = 1;
    } else if (dayStep == 6) {
        if (day == 31) {
            day = 30;
        } else {
            day += 1;
        }
    } else if (dayStep == 8) {
        if (day <= 7) {
            day = 7;
        } else if (day <= 14) {
            day = 14;
        } else if (day <= 21) {
            day = 21;
        } else {
            day = 28;
        }
    } else if (dayStep == 12 || dayStep == 13 || dayStep == 28 || dayStep == 52) {
        day = 1;
    } else if (dayStep == 10) {
        if (month <= 6) {
            day = 1;
        } else {
            day = 16;
        }
    }

    return year * 10000 + month * 100 + day;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep == 1) {
        return timeBucket; // No compression needed
    }
    long day = timeBucket % 100;
    if (dayStep == 11) {
        if (day >= 1 && day <= 10) {
            day = 1;
        } else if (day >= 11 && day <= 20) {
            day = 11;
        } else if (day >= 21 && day <= 30) {
            day = 21;
        } else {
            day = 30;
        }
    } else if (dayStep == 2) {
        if (day % 7 == 1) {
            day -= 6;
        } else if (day % 7 == 2) {
            day -= 5;
        } else if (day % 7 == 3) {
            day -= 4;
        } else if (day % 7 == 4) {
            day -= 3;
        } else if (day % 7 == 5) {
            day -= 2;
        } else if (day % 7 == 6) {
            day -= 1;
        } else {
            day -= 0;
        }
    } else if (dayStep == 12) {
        if (day % 4 == 1) {
            day -= 3;
        } else if (day % 4 == 2) {
            day -= 2;
        } else if (day % 4 == 3) {
            day -= 1;
        } else {
            day -= 0;
        }
    }
    return timeBucket / 100 * 100 + day;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 100000000L);
    int month = (int) (timeBucket / 10000 % 100);
    int day = (int) (timeBucket % 100);

    if (dayStep > 1) {
        day = (day / dayStep) * dayStep;
    }

    return year * 100000000L + month * 10000 + day;
}

