public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
        int size = 0;
        for (int i = index; i < index + len; i++) {
            char c = str.charAt(i);
            if (c >= 0 && c <= 127) {
                // 1 byte for ASCII characters
                size++;
            } else if (c >= 128 && c <= 2047) {
                // 2 bytes for characters in the range [\u0080, \u07FF]
                size += 2;
            } else if (c >= 2048 && c <= 65535) {
                // 3 bytes for characters in the range [\u0800, \uFFFF]
                size += 3;
            } else {
                // 4 bytes for characters in the range [\u10000, \u10FFFF]
                size += 4;
            }
        }
        return size;
    }

private static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size++;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (c <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            size += 1;
        } else if (c < 0x800) {
            size += 2;
        } else if (c < 0x10000) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

