public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value != null) {
        value = performVariableSubstitution(value, props);
    }
    return value;
}

private static String performVariableSubstitution(String value, Properties props) {
    int startIndex = value.indexOf("${");
    while (startIndex != -1) {
        int endIndex = value.indexOf("}", startIndex);
        if (endIndex != -1) {
            String variableName = value.substring(startIndex + 2, endIndex);
            String variableValue = props.getProperty(variableName);
            if (variableValue != null) {
                value = value.substring(0, startIndex) + variableValue + value.substring(endIndex + 1);
            }
            startIndex = value.indexOf("${");
        } else {
            break;
        }
    }
    return value;
}

