public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        List<PathSegmentImpl> pathSegments = new ArrayList<>();
        try {
            String path = u.getPath();
            if (path == null || path.isEmpty()) {
                return pathSegments;
            }
            if (path.startsWith("/")) {
                path = path.substring(1);
            }
            String[] segments = path.split("/");
            for (String segment : segments) {
                if (decode) {
                    segment = URLDecoder.decode(segment, StandardCharsets.UTF_8.name());
                }
                pathSegments.add(new PathSegmentImpl(segment));
            }
        } catch (URISyntaxException e) {
            e.printStackTrace();
        }
        return pathSegments;
    }

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String path = u.getPath();
    if (path != null) {
        if (path.startsWith("/")) {
            path = path.substring(1);
        }
        List<String> segmentStrings = split(path, "/");
        for (String segment : segmentStrings) {
            if (decode) {
                segment = URLDecoder.decode(segment, StandardCharsets.UTF_8);
            }
            segments.add(new PathSegmentImpl(segment));
        }
    }
    return segments;
}

