public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    boolean escape = false;
    for (char c : str.toCharArray()) {
        if (escape) {
            switch (c) {
                case 'b': sb.append('\b'); break;
                case 't': sb.append('\t'); break;
                case 'n': sb.append('\n'); break;
                case 'f': sb.append('\f'); break;
                case 'r': sb.append('\r'); break;
                case '"': sb.append('"'); break;
                case '\'': sb.append('\''); break;
                case '\\': sb.append('\\'); break;
                default: sb.append('\\').append(c); break;
            }
            escape = false;
        } else if (c == '\\') {
            escape = true;
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = str.length();
    boolean lastBackslash = false;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (lastBackslash) {
                sb.append '\\'');
                lastBackslash = false;
            } else {
                lastBackslash = true;
            }
        } else {
            if (lastBackslash) {
                switch (c) {
                    case 'b':
                        sb.append '\b';
                        break;
                    case 't':
                        sb.append '\t';
                        break;
                    case 'n':
                        sb.append '\n';
                        break;
                    case 'f':
                        sb.append '\f';
                        break;
                    case 'r':
                        sb.append '\r';
                        break;
                    case '\"':
                        sb.append '\"';
                        break;
                    case '\'':
                        sb.append '\'';
                        break;
                    case '\\':
                        sb.append '\\';
                        break;
                    default:
                        throw new Exception("Invalid escape character: " + c);
                }
                lastBackslash = false;
            } else {
                sb.append c;
            }
        }
    }
    if (lastBackslash) {
        throw new Exception("Escape character at end of string");
    }
    return sb.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '\\' && i + 1 < str.length()) {
            char nextCh = str.charAt(i + 1);
            switch (nextCh) {
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                default:
                    sb.append(ch);
                    sb.append(nextCh);
                    i++;
                    break;
            }
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
}

