private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    while (!circulator.isDone()) {
        Node currentNode = circulator.currentNode();
        if (predicate.test(currentNode) || currentNode == stop) {
            return circulator;
        }
        circulator.goToNext();
    }
    return circulator; // Returns the stop node if no matching node is found
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    while (start != stop) {
        if (predicate.test(start)) {
            return new OuterFaceCirculator(start);
        }
        start = start.getNextNode(dir);
    }
    return new OuterFaceCirculator(stop);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    while (!circulator.done()) {
        Node currentNode = circulator.current();
        if (predicate.test(currentNode)) {
            return circulator;
        }
        if (currentNode.equals(stop)) {
            return circulator;
        }
        circulator.next();
    }
    return circulator;
}

