protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Create a list to store the vertices of the tour
    List<V> tourVertices = new ArrayList<>();

    // Iterate through each edge in the tour set
    Iterator<E> iterator = tour.iterator();
    if (iterator.hasNext()) {
        E firstEdge = iterator.next();
        tourVertices.add(graph.getEdgeSource(firstEdge));
    }

    // Add vertices connected by edges in the tour set
    while (iterator.hasNext()) {
        E edge = iterator.next();
        tourVertices.add(graph.getEdgeTarget(edge));
    }

    // Close the tour by adding the source vertex of the first edge
    if (!tour.isEmpty()) {
        E firstEdge = tour.iterator().next();
        tourVertices.add(graph.getEdgeSource(firstEdge));
    }

    // Create and return the GraphPath
    return new DefaultGraphPath<>(graph, tourVertices);
}

